parameters.jsCode:
const body = $input.first().json.body ?? {};

const {
  cliente_id,
  titulo,
  descricao,
  prioridade,
} = body;

const erros = [];

const PRIORIDADES_PERMITIDAS = [
  'baixa',
  'media',
  'alta',
];

const isUuid = (value) =>
  typeof value === 'string' &&
  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/.test(
    value,
  );

if (
  cliente_id === undefined ||
  cliente_id === null ||
  cliente_id === ''
) {
  erros.push('cliente_id é obrigatório');
} else if (typeof cliente_id !== 'string') {
  erros.push('cliente_id deve ser um texto');
} else if (!isUuid(cliente_id.trim())) {
  erros.push('cliente_id deve ser um UUID válido');
}

if (
  titulo === undefined ||
  titulo === null ||
  titulo === ''
) {
  erros.push('título é obrigatório');
} else if (typeof titulo !== 'string') {
  erros.push('título deve ser um texto');
} else if (titulo.trim().length < 2) {
  erros.push('título deve ter pelo menos 2 caracteres');
}

if (
  descricao === undefined ||
  descricao === null ||
  descricao === ''
) {
  erros.push('descrição é obrigatória');
} else if (typeof descricao !== 'string') {
  erros.push('descrição deve ser um texto');
} else if (descricao.trim().length < 8) {
  erros.push('descrição deve ter pelo menos 8 caracteres');
}

if (
  prioridade !== undefined &&
  prioridade !== null &&
  prioridade !== ''
) {
  if (typeof prioridade !== 'string') {
    erros.push('prioridade deve ser um texto');
  } else if (
    !PRIORIDADES_PERMITIDAS.includes(prioridade.trim())
  ) {
    erros.push(
      'prioridade inválida; use baixa, media ou alta',
    );
  }
}

return {
  cliente_id:
    typeof cliente_id === 'string'
      ? cliente_id.trim()
      : cliente_id,

  titulo:
    typeof titulo === 'string'
      ? titulo.trim()
      : titulo,

  descricao:
    typeof descricao === 'string'
      ? descricao.trim()
      : descricao,

  prioridade:
    typeof prioridade === 'string' && prioridade.trim()
      ? prioridade.trim()
      : 'media',

  erros,
  valido: erros.length === 0,

  trace_id: $execution.id,
  started_at: Date.now(),
};

const query = $json.query ?? {};

const STATUS_VALIDOS = [
  'aberto',
  'em_atendimento',
  'aguardando_cliente',
  'resolvido',
  'cancelado'
];

const PRIORIDADES_VALIDAS = [
  'baixa',
  'media',
  'alta'
];

const status = query.status?.trim() || null;
const prioridade = query.prioridade?.trim() || null;

const erros = [];

if (status && !STATUS_VALIDOS.includes(status)) {
  erros.push('status inválido');
}

if (prioridade && !PRIORIDADES_VALIDAS.includes(prioridade)) {
  erros.push('prioridade inválida');
}

if (erros.length > 0) {
  return {
      valido: false,
      erros,
      trace_id: $execution.id,
      started_at: Date.now(),
    }
}

let sql = `
  select
    t.*,
    c.nome as cliente_nome
  from tickets t
  join clientes c on c.id = t.cliente_id
  where 1=1
`;

const params = [];

if (status) {
  params.push(status);
  sql += ` and t.status = $${params.length}`;
}

if (prioridade) {
  params.push(prioridade);
  sql += ` and t.prioridade = $${params.length}`;
}

sql += ' order by t.criado_em desc';

return {
  valido: true,
  sql,
  params,
  trace_id: $execution.id,
  started_at: Date.now(),
}

